<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_admin_queue() { if ( ! current_user_can( 'sd_review_reports' ) ) { wp_die( esc_html__( 'You are not allowed to view this page.', 'social-discovery-core' ) ); } global $wpdb; $t = sd_core_table_names(); $rows = $wpdb->get_results( "SELECT * FROM {$t['reports']} ORDER BY id DESC LIMIT 50" ); ?><div class="wrap"><h1><?php esc_html_e( 'Moderation Queue', 'social-discovery-core' ); ?></h1><table class="widefat striped"><thead><tr><th>ID</th><th><?php esc_html_e( 'Type', 'social-discovery-core' ); ?></th><th><?php esc_html_e( 'Reason', 'social-discovery-core' ); ?></th><th><?php esc_html_e( 'Status', 'social-discovery-core' ); ?></th><th><?php esc_html_e( 'Date', 'social-discovery-core' ); ?></th><th><?php esc_html_e( 'Action', 'social-discovery-core' ); ?></th></tr></thead><tbody><?php if ( empty( $rows ) ) : ?><tr><td colspan="6"><?php esc_html_e( 'No reports found.', 'social-discovery-core' ); ?></td></tr><?php else : foreach ( $rows as $row ) : ?><tr><td><?php echo esc_html( $row->id ); ?></td><td><?php echo esc_html( $row->target_type . ' #' . $row->target_id ); ?></td><td><?php echo esc_html( $row->reason ); ?></td><td><?php echo esc_html( $row->status ); ?></td><td><?php echo esc_html( $row->created_at ); ?></td><td><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><?php wp_nonce_field( 'sd_report_status_' . $row->id ); ?><input type="hidden" name="action" value="sd_report_status"><input type="hidden" name="report_id" value="<?php echo esc_attr( $row->id ); ?>"><select name="status"><option value="under_review">Under review</option><option value="resolved">Resolved</option><option value="dismissed">Dismissed</option></select><button class="button" type="submit"><?php esc_html_e( 'Update', 'social-discovery-core' ); ?></button></form></td></tr><?php endforeach; endif; ?></tbody></table></div><?php }
function sd_core_admin_report_status() { $id = absint( $_POST['report_id'] ?? 0 ); check_admin_referer( 'sd_report_status_' . $id ); if ( ! current_user_can( 'sd_review_reports' ) ) { wp_die( esc_html__( 'Unauthorized.', 'social-discovery-core' ), 403 ); } sd_core_update_report( $id, sanitize_key( $_POST['status'] ?? '' ) ); wp_safe_redirect( admin_url( 'admin.php?page=sd-moderation-queue' ) ); exit; }
add_action( 'admin_post_sd_report_status', 'sd_core_admin_report_status' );
